from pathlib import Path
import json,html,shutil
r=Path(__file__).resolve().parents[1]
projects=json.loads((r/'supporting-site-files/projects.json').read_text(encoding='utf-8'))
E=html.escape

def header(base):return f'''<a class="skip" href="#main">Skip to content</a><header class="site-header"><a class="brand" href="{base}"><span class="monogram" aria-hidden="true">bj.</span><span>Ben Janning<small>Data · Software · Business</small></span></a><nav aria-label="Main navigation"><a href="{base}#projects">Projects</a><a href="{base}#about">About</a><a href="{base}#skills">Skills</a><a href="https://github.com/benjanning">GitHub <span aria-hidden="true">↗</span></a></nav></header>'''
def footer(base):return f'''<footer><a class="footer-name" href="{base}">Ben Janning<span>Useful technology. Clearly explained.</span></a><div><a href="https://github.com/benjanning">Explore my GitHub ↗</a><small>Selected academic projects · Built with care</small></div></footer>'''
def page(title,desc,body,base='./',slug=''):
 canonical='https://benjanning.github.io/projects/'+slug
 return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{E(title)} | Ben Janning</title><meta name="description" content="{E(desc)}"><meta name="theme-color" content="#f6f5ef"><meta property="og:title" content="{E(title)} | Ben Janning"><meta property="og:description" content="{E(desc)}"><meta property="og:type" content="website"><meta property="og:url" content="{canonical}"><meta property="og:image" content="https://benjanning.github.io/projects/assets/images/car-inventory.jpg"><link rel="canonical" href="{canonical}"><link rel="icon" href="{base}assets/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="{base}assets/style.css"><script src="{base}assets/site.js" defer></script></head><body>{header(base)}{body}{footer(base)}</body></html>'''

def tags(p):return '<ul class="tags" aria-label="Technologies">'+''.join(f'<li>{E(s)}</li>' for s in p['stack'])+'</ul>'
def demo_link(p):return f'<a class="demo-link" href="{p["demo"]}">Try demo ↗</a>' if p.get('demo') else ''
def card(p,i):return f'''<article class="project-card" data-category="{E(p['category'])}"><a class="card-image {p['slug']}" href="projects/{p['slug']}/" tabindex="-1" aria-hidden="true"><img src="assets/{p['image']}" alt="" loading="lazy" width="1000" height="650"></a><div class="card-body"><div class="eyebrow">0{i+1} <span>—</span> {E(p['category'])}</div><h3><a href="projects/{p['slug']}/">{E(p['title'])} <span aria-hidden="true">↗</span></a></h3><p>{E(p['desc'])}</p>{tags(p)}<div class="card-links">{demo_link(p)}<a href="projects/{p['slug']}/">View case study <span aria-hidden="true">→</span></a><a href="https://github.com/benjanning/{p['repo']}" aria-label="Source code for {E(p['title'])}">Source ↗</a></div></div></article>'''
body=f'''<main id="main" tabindex="-1"><section class="hero"><div class="hero-copy"><div class="eyebrow"><span class="dot"></span>Data analytics & software development</div><h1>Useful technology.<br><em>Clearer decisions.</em></h1><p class="hero-intro">I’m Ben. I connect data, software and practical business thinking to build things people can understand and use.</p><div class="actions"><a class="button" href="#projects">Explore my work <span aria-hidden="true">↘</span></a><a class="text-link" href="https://github.com/benjanning">GitHub profile ↗</a></div><p class="hero-note">Python · SQL · Web applications · Statistical analysis</p></div><figure class="hero-visual"><div class="visual-topline"><span class="dot"></span>FROM SOURCE CODE TO SOMETHING USEFUL</div><div class="browser-frame"><div class="frame-bar"><i></i><i></i><i></i><span>Car rental management / local demo</span></div><img src="assets/images/car-inventory.jpg" alt="Working car rental application showing synthetic inventory and customer tables" width="1265" height="712" fetchpriority="high"></div><figcaption><span>01 / A working application</span><a href="projects/car-rental/">See how it works →</a></figcaption></figure></section>
<div class="intro-strip"><p>From a business question<br><strong>to a practical technical solution.</strong></p><span>Explore the data.</span><span>Build the workflow.</span><span>Explain the outcome.</span></div>
<section class="work-section" id="projects"><div class="section-heading"><div><div class="eyebrow">Selected work / 01—06</div><h2>Built to be explored.</h2></div><p>Working applications, analytical investigations and the decisions behind them.</p></div><div class="filters" hidden aria-label="Filter projects"><button class="active" data-filter="All" aria-pressed="true">All work <span>6</span></button><button data-filter="Web application" aria-pressed="false">Applications</button><button data-filter="Data analysis" aria-pressed="false">Data analysis</button><button data-filter="Machine learning" aria-pressed="false">Machine learning</button><button data-filter="Algorithms" aria-pressed="false">Algorithms</button></div><p class="sr-only" id="filter-status" aria-live="polite"></p><div class="project-grid">{''.join(card(p,i) for i,p in enumerate(projects))}</div><p class="evidence-note">Every visual comes from a running application or an actual dataset. Each case study explains what was verified and where the limits are.</p></section>
<section class="about-section" id="about"><div><div class="eyebrow">A little about me</div><h2>Technical curiosity.<br><em>Practical perspective.</em></h2></div><div class="about-copy"><p class="lead">I’m interested in the space where technology meets a real business need.</p><p>My background combines computing and data analytics study at Atlantic Technological University with commercial experience. These projects show how I work with data, build applications and communicate technical ideas clearly.</p><p>I’m interested in data analytics, software development, business intelligence, solutions engineering and technology-focused commercial roles.</p><a class="text-link" href="https://github.com/benjanning">Explore the source behind the work ↗</a></div></section>
<section class="skills-section" id="skills"><div class="section-heading"><div><div class="eyebrow">Skills in practice</div><h2>Tools, with a purpose.</h2></div><p>Capabilities demonstrated in the projects above.</p></div><div class="skill-grid"><article><span>01</span><h3>Understand the data</h3><p>Python, pandas, NumPy, SciPy, statsmodels, scikit-learn and Jupyter.</p><small>Exploration · Statistical testing · Classification</small></article><article><span>02</span><h3>Build the solution</h3><p>Flask, REST APIs, SQL/MySQL, Node.js, Express, EJS, JavaScript and HTML/CSS.</p><small>Interfaces · Data access · Application workflows</small></article><article><span>03</span><h3>Make it clear</h3><p>Matplotlib, Seaborn, Git, reproducible experiments and straightforward documentation.</p><small>Visual evidence · Testing · Technical communication</small></article></div></section></main>'''
(r/'index.html').write_text(page('Data, software & practical thinking','Selected applications and data analytics projects by Ben Janning. Explore working prototypes, genuine visuals and clear case studies.',body),encoding='utf-8')
for i,p in enumerate(projects):
 base='../../';src='https://github.com/benjanning/'+p['repo'];nextp=projects[(i+1)%len(projects)]
 extra=f'''<figure class="evidence-figure"><a href="../../assets/{p['extra']}"><img src="../../assets/{p['extra']}" alt="Original saved coursework output for {E(p['title'])}" loading="lazy"></a><figcaption>Original saved coursework output, retained alongside the new presentation. Open image to inspect.</figcaption></figure>''' if p['extra'] else ''
 gallery=''.join(f'<figure class="evidence-figure"><a href="../../assets/{img}"><img src="../../assets/{img}" alt="{E(caption)}" loading="lazy"></a><figcaption>{E(caption)}</figcaption></figure>' for img,caption in p.get('gallery',[]))
 b=f'''<main id="main" tabindex="-1" class="case-page"><a class="back-link" href="../../#projects">← All projects</a><section class="case-hero"><div class="eyebrow">0{i+1} / {E(p['category'])}</div><h1>{E(p['title'])}<span>.</span></h1><p class="case-summary">{E(p['desc'])}</p>{tags(p)}<div class="actions">{('<a class="button" href="'+p["demo"]+'">Try static demo ↗</a>') if p.get("demo") else ''}<a class="button" href="{src}">Explore the code ↗</a><a class="text-link" href="#technical">Run locally ↓</a></div>{('<p class="demo-disclosure">Public demo: browser-based static version. The Express/MySQL implementation is available in the source.</p>') if p.get("demo") else ''}</section><figure class="case-cover {p['slug']}"><a href="../../assets/{p['image']}" aria-label="Open full-size project visual"><img src="../../assets/{p['image']}" alt="{E(p['alt'])}" width="1100" height="730"></a><figcaption>{E(p['caption'])}</figcaption></figure><div class="case-content"><aside><div class="eyebrow">Inside this project</div><a href="#overview">What I built</a><a href="#process">How it works</a><a href="#evidence">Evidence & limits</a><a href="#technical">Technical details</a></aside><div><section id="overview"><div class="eyebrow">The project</div><h2>What I built</h2><p class="lead">{E(p['built'])}</p><h3>Why it matters</h3><p>{E(p['why'])}</p></section><section id="process"><h2>How it works</h2><ol class="steps">{''.join(f'<li><span>0{j+1}</span><p>{E(v)}</p></li>' for j,v in enumerate(p['how']))}</ol><h3>What it demonstrates</h3><p>{E(p['demonstrates'])}</p></section><section id="evidence"><h2>Evidence, with context.</h2><div class="result-box"><span class="eyebrow">Verified in this review</span><p>{E(p['result'])}</p></div>{extra}{gallery}<h3>Scope and limitations</h3><p>{E(p['limits'])}</p><p class="small">Visual provenance and source attribution are recorded in <a href="https://github.com/benjanning/projects/blob/main/assets/PROVENANCE.md">the evidence register ↗</a>.</p></section><section id="technical"><h2>Under the surface.</h2><details open><summary>Architecture, methods and improvements</summary><p>{E(p['technical'])}</p></details><details><summary>Try it locally</summary><p>{E(p['run'])}</p><p>The portfolio is a static GitHub Pages site. Server applications run locally; the portfolio does not collect bookings, credentials or payments.</p></details><a class="text-link" href="{src}">Read the source and setup instructions ↗</a></section></div></div><a class="next-project" href="../{nextp['slug']}/"><span class="eyebrow">Next project</span><strong>{E(nextp['title'])} →</strong></a></main>'''
 d=r/'projects'/p['slug'];d.mkdir(exist_ok=True);(d/'index.html').write_text(page(p['title'],p['desc'],b,base,'projects/'+p['slug']+'/'),encoding='utf-8')
(r/'404.html').write_text(page('Page not found','Return to the selected projects.', '<main id="main" tabindex="-1" class="case-page"><h1>Let’s get you back.</h1><p>This page could not be found.</p><a class="button" href="/projects/">Explore the projects →</a></main>', '/projects/'),encoding='utf-8')
(r/'assets/favicon.svg').write_text('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64"><rect width="64" height="64" rx="16" fill="#214b3b"/><text x="10" y="44" font-family="Georgia,serif" font-size="38" fill="#f6f5ef">bj.</text></svg>')
(r/'assets/site.js').write_text('''const filters = document.querySelector('.filters');
if (filters) {
  filters.hidden = false;
  const cards = [...document.querySelectorAll('.project-card')];
  filters.addEventListener('click', event => {
    const button = event.target.closest('button[data-filter]');
    if (!button) return;
    filters.querySelectorAll('button').forEach(item => {
      item.classList.toggle('active', item === button);
      item.setAttribute('aria-pressed', String(item === button));
    });
    cards.forEach(card => {card.hidden = button.dataset.filter !== 'All' && card.dataset.category !== button.dataset.filter;});
    const count = cards.filter(card => !card.hidden).length;
    document.querySelector('#filter-status').textContent = `${count} projects shown`;
  });
}
''')
print('Homepage and six complete case study pages generated.')
